// app.ts
export function createApp(userRepository: IUserRepository) {
const app = express();
app.use(express.json());
 app.post('/users', async (req, res) => {
  const user = await userRepository.save(req.body);
  res.status(201).json(user);
});
 return app;
}
// app.test.ts
